            _notExistsVMethod(_did, _vMethodId),
            IDidVerificationMethod.VerificationMethodExists(_did, _vMethodId)
        );
    }

    function _checkVMethodExists(
        bytes32 _did,
        bytes32 _vMethodId
    ) internal view {
